import { Component, Prop, h, Host, Event, EventEmitter, Element } from '@stencil/core';
import classNames from 'classnames';
import { ArrowPaginationValue } from '../types';
import { dir } from '@src/shared/i18n';
import { KsIconChevronLeft, KsIconChevronRight } from '@fe-infra/keystone-icons-stencil';

const prefix = 'arrow-button';

@Component({
  tag: 'ks-arrow-button',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsArrowButton {
  @Element() el!: HTMLKsArrowButtonElement;
  /** Show the component; triggers the enter or exit states */

  @Prop() currentIndex = -1;

  @Prop() count = 0;

  @Prop() slidesToShow = 1;

  @Prop() infinite = false;

  @Prop() orient: 'left' | 'right' = 'left';

  @Prop() disabled = false;

  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<ArrowPaginationValue>;

  render() {
    return (
      <Host dir={dir()} class="KsArrowButton">
        <ks-icon-button size="sm" variant="text" disabled={this.disabled}>
          {this.orient === 'left' ? (
            <KsIconChevronLeft class={classNames({ [`${prefix}--arrow`]: !this.disabled })} />
          ) : (
            <KsIconChevronRight class={classNames({ [`${prefix}--arrow`]: !this.disabled })} />
          )}
        </ks-icon-button>
      </Host>
    );
  }
}
